<script setup lang="ts">
import { computed, ref } from 'vue'
import { lessons } from '../data/content'
import { useLearning } from '../stores/learning'
import { useNavigation } from '../stores/navigation'
import AppIcon from '../components/AppIcon.vue'
import LessonNotes from '../components/LessonNotes.vue'
const store=useLearning(),nav=useNavigation()
const selected=ref(lessons.some(l=>l.id===nav.lessonId)?nav.lessonId:'syahadat'),text=ref(''),linkedLesson=ref(''),showAnswered=ref(false)
const shown=computed(()=>store.state.questions.filter(q=>q.answered===showAnswered.value).slice().reverse())
function changeStatus(id:string){store.toggleQuestion(id);showAnswered.value=store.state.questions.find(q=>q.id===id)?.answered || false}
function add(){if(!text.value.trim())return;store.addQuestion(text.value.trim(),linkedLesson.value||null);text.value='';document.getElementById('new-question')?.focus()}
</script>
<template><div class="page-heading"><div><p class="eyebrow">SIMPAN PEMAHAMAN DAN RASA INGIN TAHU</p><h1>Catatan dan pertanyaan</h1><p>Tidak harus langsung paham. Beri ruang untuk bertanya.</p></div></div><div class="notes-layout"><section class="card"><h2>Catatan per pelajaran</h2><label for="note-lesson" class="field-label">Pilih pelajaran</label><select id="note-lesson" v-model="selected" class="form-input"><option v-for="l in lessons" :key="l.id" :value="l.id">{{l.title}}</option></select><LessonNotes :key="selected" :lesson-id="selected"/></section><section class="card"><h2>Pertanyaan untuk guru</h2><p class="muted text-sm mt-2">Simpan dulu, lalu tanyakan kepada guru, ustaz, atau pengurus masjid. Pertanyaan tidak dikirim ke siapa pun.</p><form @submit.prevent="add"><label for="new-question" class="field-label">Apa yang ingin kamu tanyakan?</label><textarea id="new-question" v-model="text" class="form-input" rows="3" maxlength="2000" placeholder="Saya ingin memahami lebih jauh tentang…" required></textarea><label for="question-lesson" class="field-label">Terkait pelajaran (opsional)</label><select id="question-lesson" v-model="linkedLesson" class="form-input"><option value="">Pertanyaan umum</option><option v-for="l in lessons" :key="l.id" :value="l.id">{{l.title}}</option></select><button class="button primary mt-4" type="submit" :disabled="!text.trim()"><AppIcon name="plus" :size="16"/>Simpan pertanyaan</button></form><div class="filter-row question-filters"><button class="filter-chip" :class="{selected:!showAnswered}" :aria-pressed="!showAnswered" @click="showAnswered=false">Belum dijawab · {{store.state.questions.filter(q=>!q.answered).length}}</button><button class="filter-chip" :class="{selected:showAnswered}" :aria-pressed="showAnswered" @click="showAnswered=true">Sudah dijawab · {{store.state.questions.filter(q=>q.answered).length}}</button></div><article v-for="q in shown" :key="q.id" class="teacher-question"><p class="question-text">{{q.text}}</p><span v-if="q.lessonId" class="small-note">{{lessons.find(l=>l.id===q.lessonId)?.title}}</span><label class="check-row"><input type="checkbox" :checked="q.answered" @change="changeStatus(q.id)"/>Sudah dijawab oleh guru</label><details><summary>Catat jawaban guru</summary><label :for="`answer-${q.id}`" class="sr-only">Jawaban guru untuk {{q.text}}</label><textarea :id="`answer-${q.id}`" class="form-input mt-3" :value="q.answer" rows="3" maxlength="10000" placeholder="Tuliskan jawaban beserta nama guru dan sumbernya…" @change="store.saveAnswer(q.id,($event.target as HTMLTextAreaElement).value)"></textarea></details></article><p v-if="!shown.length" class="empty-note">{{showAnswered?'Belum ada pertanyaan yang ditandai sudah dijawab.':'Belum ada pertanyaan. Rasa ingin tahumu boleh tumbuh perlahan.'}}</p></section></div></template>
